"""NIST ACVP ML-DSA-87 keyGen / sigGen / sigVer vectors, parsed from the generated
C header.

``hw/sys/sep/dv/fw/tests/common/abr_nist_vectors.h`` is generated by
``fw/tests/common/gen_abr_nist_vectors.py`` from the NIST ACVP-Server
internalProjection. This module is the Python golden for the no_cpu KATs; it
does not re-encode the words.

The sigGen and sigVer groups are the external-mu variants (ACVP tgId 11), so a
test drives ``MLDSA_EXTERNAL_MU`` and writes mu rather than a raw message.

These are transcribed authority values, not a recomputable construction, so
there is no independent self-test available the way ``sep_hmac_golden`` checks
itself against RFC 4231. The import-time assertions below are shape and
non-degeneracy only, and that limit is real: they would not catch a
transcription error that preserved length. The defence is that the header is
generated, never hand-edited.
"""

from __future__ import annotations

import re
from pathlib import Path

_HEADER = Path(__file__).resolve().parents[2] / "fw" / "tests" / "common" / "abr_nist_vectors.h"


def _load_u32_array(name: str) -> list[int]:
    text = _HEADER.read_text(encoding="utf-8")
    m = re.search(
        rf"static const uint32_t {name}\[(\d+)\] = \{{(.*?)\}};",
        text,
        re.S,
    )
    if not m:
        raise RuntimeError(f"{name} not found in {_HEADER}")
    words = [int(tok, 16) for tok in re.findall(r"0x([0-9a-fA-F]+)u", m.group(2))]
    n = int(m.group(1))
    if len(words) != n:
        raise RuntimeError(f"{name}: parsed {len(words)} words, header says {n}")
    return words


def _load_define(name: str) -> int:
    """One ``#define <name> <int>`` from the header (the sigVer verdicts)."""
    text = _HEADER.read_text(encoding="utf-8")
    m = re.search(rf"^#define {name}\s+(\d+)\s*$", text, re.M)
    if not m:
        raise RuntimeError(f"{name} not found in {_HEADER}")
    return int(m.group(1))


# keyGen (ACVP tcId 51)
NIST_KG_SEED = _load_u32_array("nist_kg_seed")
NIST_KG_PK = _load_u32_array("nist_kg_pk")

# sigGen, deterministic + external mu (ACVP tcId 151)
NIST_SG_SK = _load_u32_array("nist_sg_sk")
NIST_SG_MU = _load_u32_array("nist_sg_mu")
NIST_SG_SIG = _load_u32_array("nist_sg_sig")

# sigVer: one case the standard says must verify (tcId 154) and one that must
# not (tcId 151). The rejecting case fails an engine that reports success
# unconditionally (VERIFY_RES equals the submitted c~ for every input).
NIST_SV_OK_PK = _load_u32_array("nist_sv_ok_pk")
NIST_SV_OK_MU = _load_u32_array("nist_sv_ok_mu")
NIST_SV_OK_SIG = _load_u32_array("nist_sv_ok_sig")
NIST_SV_OK_VERDICT = _load_define("NIST_SV_OK_VERDICT")

NIST_SV_BAD_PK = _load_u32_array("nist_sv_bad_pk")
NIST_SV_BAD_MU = _load_u32_array("nist_sv_bad_mu")
NIST_SV_BAD_SIG = _load_u32_array("nist_sv_bad_sig")
NIST_SV_BAD_VERDICT = _load_define("NIST_SV_BAD_VERDICT")

# Shapes, from the header's own word-count defines rather than repeated here.
assert len(NIST_KG_SEED) == 8
assert len(NIST_KG_PK) == 648
assert len(NIST_SG_SK) == 1224
assert len(NIST_SG_MU) == 16
assert len(NIST_SG_SIG) == 1157
for _name, _v in (
    ("NIST_SV_OK_PK", NIST_SV_OK_PK),
    ("NIST_SV_BAD_PK", NIST_SV_BAD_PK),
):
    assert len(_v) == 648, _name
for _name, _v in (
    ("NIST_SV_OK_SIG", NIST_SV_OK_SIG),
    ("NIST_SV_BAD_SIG", NIST_SV_BAD_SIG),
):
    assert len(_v) == 1157, _name

# Non-degeneracy: an all-zero vector would make a compare pass against a dead
# register window.
for _name, _v in (
    ("NIST_KG_SEED", NIST_KG_SEED),
    ("NIST_KG_PK", NIST_KG_PK),
    ("NIST_SG_SK", NIST_SG_SK),
    ("NIST_SG_MU", NIST_SG_MU),
    ("NIST_SG_SIG", NIST_SG_SIG),
    ("NIST_SV_OK_SIG", NIST_SV_OK_SIG),
    ("NIST_SV_BAD_SIG", NIST_SV_BAD_SIG),
):
    assert any(w != 0 for w in _v), f"{_name} is all zero"

# The two verdicts must differ, or the accept/reject pair proves nothing.
assert NIST_SV_OK_VERDICT != NIST_SV_BAD_VERDICT, (
    "sigVer accept and reject cases carry the same verdict; the pair would not be able to fail"
)
# And the two cases must actually be different inputs.
assert NIST_SV_OK_SIG != NIST_SV_BAD_SIG or NIST_SV_OK_PK != NIST_SV_BAD_PK, (
    "sigVer accept and reject cases have identical inputs"
)
